CREATE OR REPLACE VIEW `vwprovv2cogedetail` AS select `p`.`data_status` AS `data_status`,abs(`p`.`importo`) AS `importo`,`p`.`status_compenso` AS `status_compenso`,`p`.`status_pratica` AS `status_pratica`,`p`.`cognome` AS `cognome`,`p`.`denominazione_riferimento` AS `denominazione_riferimento`,`p`.`id` AS `provvigioni_id`,`p`.`entrata_uscita` AS `entrata_uscita`,`p`.`fonte` AS `fonte`,(curdate() - interval dayofmonth(curdate()) day) AS `datacontabile` from `provvigioni` `p` where ((`p`.`data_status` >= ((curdate() - interval (dayofmonth(curdate()) - 1) day) - interval 1 month)) and (`p`.`data_status` <= (curdate() - interval dayofmonth(curdate()) day)) and (`p`.`status_pratica` in ('PERFEZIONATA','IN AMMORTAMENTO'))) order by `p`.`entrata_uscita`,`p`.`data_status`
